def normalize(vec):
    norm = math.sqrt(sum(x * x for x in vec))
    if norm == 0:
        return vec
    return [x / norm for x in vec]

def embed_text(text):
    result = genai.embed_content(
        model="models/gemini-embedding-001",
        content=text,
        task_type="retrieval_document",
        output_dimensionality=EMBEDDING_DIM
    )
    return normalize(result["embedding"])

def make_chunks(course):
    name = course["courseName"]
    return [
        {"chunk_type": "overview", "text": f"Course: {name}. Faculty: {course['faculty']}. Duration: {course['duration']}. Entry requirements: {course['entryRequirements']}. Description: {course['description']}"},
        {"chunk_type": "modules", "text": f"Course: {name}. Modules covered: {', '.join(course['modules'])}"},
        {"chunk_type": "fees", "text": f"Course: {name}. Total fees: {course['fees']}"},
        {"chunk_type": "pathways", "text": f"Course: {name}. Pathways after completion: {', '.join(course['pathways'])}"},
        {"chunk_type": "careers", "text": f"Course: {name}. Career opportunities: {', '.join(course['careerOpportunities'])}"},
    ]

def seed():
    col = get_collection()
    col.delete_many({})
    all_chunks = []
    for i, course in enumerate(COURSES):
        for chunk in make_chunks(course):
            chunk["course_name"] = course["courseName"]
            chunk["faculty"] = course["faculty"]
            chunk["embedding"] = embed_text(chunk["text"])
            chunk["source"] = course["courseName"]
            all_chunks.append(chunk)
        print(f"[{i+1}/{len(COURSES)}] {course['courseName']}")
        time.sleep(1.5)
    col.insert_many(all_chunks)
    print(f"Done. Inserted {len(all_chunks)} chunks from {len(COURSES)} courses.")

if __name__ == "__main__":
    seed()